function plan(api) {
  api.terrain('plain', { amplitude: 1.6, roughness: 0.3, seed: api.seed });

  const candidates = [[0, -7], [-5, -9], [5, -6]];
  const observations = candidates.map(function (p) {
    const center = api.environmentSample(p);
    const edges = [[-27, 0], [27, 0], [0, -23], [0, 23]].map(function (d) {
      return api.environmentSample([p[0] + d[0], p[1] + d[1]]);
    });
    const heights = edges.map(function (s) { return s.height; }).concat([center.height]);
    return {
      point: p,
      height: center.height,
      relief: Math.max.apply(null, heights) - Math.min.apply(null, heights),
      slope: center.slope
    };
  });
  observations.sort(function (a, b) {
    return a.relief - b.relief || a.slope - b.slope;
  });
  const site = observations[0];
  const cx = site.point[0];
  const cz = site.point[1];

  api.sculptTerrain({
    mode: 'flatten',
    point: [cx, cz],
    radius: 34,
    strength: 1,
    targetHeight: site.height
  });
  const ground = api.environmentSample([cx, cz]).height;

  api.requireAsset({
    key: 'arena',
    name: '王城斗兽场',
    role: 'structure',
    dimensions: [58, 15, 48],
    prompt: 'One grand medieval stone amphitheater, Y+ up, Z+ front entrance, X+ right. Complete elliptical freestanding building 58m wide and 48m deep, 15m high, open to the sky, with a large unobstructed sunken-looking sand arena at ground level. Three monumental tiers of weathered pale limestone arcades, heavy piers, buttresses, crenellated upper parapet, carved heraldic shields and restrained burgundy banners. Interior continuous stepped stone spectator seating surrounds a 30m by 21m oval sand floor, with radial stair aisles and vaulted access tunnels. Wide ground-level front entrance on Z+, matching rear and side entrances, all genuinely open and connected to arena and internal circulation. Grand royal viewing box opposite front entrance with burgundy canopy. Thick convincing masonry, subtle age and chipped edges, largely intact majestic architecture. Bottom at ground level, no external landscape, no roof over arena, no people.'
  });
  api.requireAsset({
    key: 'statue',
    name: '石狮卫像',
    role: 'environment',
    dimensions: [2.4, 4.2, 3],
    prompt: 'One medieval carved limestone seated heraldic lion on a square stone pedestal, aged pale stone, powerful silhouette, shield beneath forepaws. Y+ up, Z+ facing front, X+ right. Standalone monument, bottom of pedestal at ground.'
  });
  api.requireAsset({
    key: 'brazier',
    name: '铁铸火盆',
    role: 'environment',
    dimensions: [1.2, 2.3, 1.2],
    prompt: 'One medieval wrought iron brazier on a stout stone foot, dark forged basket, small glowing coals and restrained orange flame, believable crafted ironwork. Y+ up, Z+ front, X+ right, standalone.'
  });
  api.requireAsset({
    key: 'cypress',
    name: '庭院柏树',
    role: 'environment',
    dimensions: [3, 10, 3],
    prompt: 'One tall narrow Mediterranean cypress tree, dense dark green tapered foliage and a short textured trunk, natural irregular silhouette. Y+ up, Z+ front, X+ right. Standalone tree without planter or landscape.'
  });
  api.requireAsset({
    key: 'bench',
    name: '石砌长凳',
    role: 'environment',
    dimensions: [3.4, 0.9, 1],
    prompt: 'One medieval pale limestone bench, thick rectangular seat on two carved stone supports, gently worn edges and subtle moss at base. No backrest. Y+ up, Z+ front, X+ right. Standalone.'
  });
  api.requireAsset({
    key: 'banner',
    name: '王旗立柱',
    role: 'environment',
    dimensions: [1.8, 6.5, 0.8],
    prompt: 'One medieval freestanding banner standard with a heavy stone base, dark iron pole and crossbar, long burgundy hanging cloth with a muted gold heraldic lion and gold hem. Y+ up, Z+ front showing heraldry, X+ right. Standalone, realistic cloth folds.'
  });

  const arena = api.place({
    assetId: api.asset('arena'),
    position: [cx, ground, cz],
    rotationY: 0,
    role: 'structure'
  });
  api.foundation({
    under: [arena],
    shape: 'rounded-rectangle',
    width: 59,
    depth: 49,
    top: 'level',
    maxThickness: 2,
    material: 'aged limestone masonry'
  });

  api.surface({
    id: 'arena-sand',
    surface: 'sand',
    region: {
      kind: 'polygon',
      points: Array.from({ length: 32 }, function (_, i) {
        const a = i * Math.PI / 16;
        return [cx + 14.8 * Math.cos(a), cz + 10.3 * Math.sin(a)];
      })
    }
  });

  const forecourtZ = cz + 30;
  api.surface({
    id: 'ceremonial-court',
    surface: 'paving',
    material: 'weathered limestone slabs',
    region: {
      kind: 'polygon',
      points: [
        [cx - 23, cz + 23], [cx + 23, cz + 23],
        [cx + 23, 38], [cx - 23, 38]
      ]
    }
  });

  const gate = [cx, cz + 24];
  const approachStart = [cx, 45];
  const startHeight = api.environmentSample(approachStart).height;
  const gateHeight = api.environmentSample(gate).height;
  api.rampTerrain({
    start: approachStart,
    end: [cx, forecourtZ],
    width: 10,
    startHeight: startHeight,
    endHeight: gateHeight,
    softness: 0.8,
    strength: 1
  });
  api.environmentSample([cx, forecourtZ]);
  api.route({
    id: 'processional-approach',
    points: [approachStart, [cx, 37], [cx, forecourtZ], gate],
    width: 9,
    curve: 'polyline',
    surface: 'paving',
    material: 'large worn limestone blocks'
  });

  const perimeter = [];
  for (let i = 0; i <= 48; i++) {
    const angle = Math.PI / 2 + i * Math.PI * 2 / 48;
    perimeter.push([cx + 33 * Math.cos(angle), cz + 28 * Math.sin(angle)]);
  }
  api.route({
    id: 'outer-gallery-walk',
    points: perimeter,
    width: 3.4,
    curve: 'polyline',
    surface: 'paving',
    material: 'small weathered stone setts'
  });
  [[-1, 0], [1, 0], [0, -1]].forEach(function (d, i) {
    api.route({
      id: 'auxiliary-entrance-' + i,
      points: [
        [cx + d[0] * 33, cz + d[1] * 28],
        [cx + d[0] * 29, cz + d[1] * 24]
      ],
      width: 4,
      surface: 'paving'
    });
  });

  function put(key, x, z, rotation) {
    return api.place({
      assetId: api.asset(key),
      position: [x, z],
      rotationY: rotation || 0
    });
  }
  [-1, 1].forEach(function (side) {
    put('statue', cx + side * 7.5, cz + 27.5, 0);
    put('brazier', cx + side * 5.6, cz + 25.5, 0);
    put('banner', cx + side * 13, forecourtZ + 2, 0);
    put('banner', cx + side * 13, 36, 0);
    put('bench', cx + side * 20, forecourtZ + 2, -side * Math.PI / 2);
    put('bench', cx + side * 20, 35, -side * Math.PI / 2);
  });

  api.grass('outer-meadow', {
    kind: 'polygon',
    points: [[-47, -47], [47, -47], [47, 47], [-47, 47]]
  }, { preset: 'meadow', density: 0.22, height: 0.18 });

  const trees = api.sampleProbabilityField({
    bounds: { minX: -44, maxX: 44, minZ: -44, maxZ: 40 },
    maxPoints: 26,
    candidates: 400,
    minDistance: 5.5,
    seed: api.seed,
    cluster: { strength: 0.2, scale: 12 }
  }, function (p) {
    const dx = p[0] - cx;
    const dz = p[1] - cz;
    const ellipse = dx * dx / (38 * 38) + dz * dz / (33 * 33);
    if (ellipse < 1 || (p[1] > cz + 20 && Math.abs(dx) < 26)) return 0;
    const s = api.environmentSample(p);
    return s.slope > 0.6 ? 0 : (p[1] < cz ? 0.8 : 0.35);
  });
  trees.forEach(function (p) {
    put('cypress', p[0], p[1], Math.random() * Math.PI * 2);
  });
  api.spawn([cx, 42], 180);
}

function plan(api) {
  api.terrain('valley', { amplitude: 12, roughness: 0.32, seed: api.seed });
  api.modifyTerrain({
    modifier: 'ridge',
    region: { kind: 'path', points: [[-46, -45], [-44, 0], [-46, 45]], width: 13 },
    amplitude: 7,
    softness: 0.8
  });
  api.modifyTerrain({
    modifier: 'ridge',
    region: { kind: 'path', points: [[46, -45], [44, 0], [46, 45]], width: 13 },
    amplitude: 7,
    softness: 0.8
  });
  api.sculptTerrain({ mode: 'flatten', point: [0, 0], radius: 5, targetHeight: 0.7, strength: 0.9 });
  api.rampTerrain({
    start: [0, -47], end: [0, 47], width: 5,
    startHeight: 0.7, endHeight: 0.7, softness: 0.7, strength: 1
  });
  const river = api.water('valley-stream', {
    type: 'river',
    points: [[0, -48], [0, -28], [0, 0], [0, 26], [0, 48]],
    width: 3.2, level: 1, depth: 0.8
  });

  api.requireAsset({
    key: 'stone-house', name: '山谷石屋', role: 'structure',
    dimensions: [5.6, 7.5, 6.3], variants: 2,
    prompt: 'One standalone compact two-storey medieval mountain village house. Thick irregular gray limestone walls, deeply recessed small wooden windows, steep dark slate gable roof, one stone chimney, weathered oak entrance door on Z+ front, modest timber shutters and subtle moss at the base. No surrounding ground or vegetation. Y+ up, Z+ entrance, X+ right.'
  });
  api.requireAsset({
    key: 'small-house', name: '窄巷石屋', role: 'structure',
    dimensions: [4.6, 6.2, 5.2],
    prompt: 'One standalone narrow two-storey stone cottage in a mountain valley village. Rough warm gray masonry, steep overlapping charcoal slate roof, small chimney, wooden shutters, plain oak door centered on Z+ front. Aged handcrafted appearance. No ground plane. Y+ up, Z+ front, X+ right.'
  });
  api.requireAsset({
    key: 'bridge', name: '石拱桥', role: 'structure',
    dimensions: [4, 2, 7],
    prompt: 'One standalone short medieval gray stone footbridge, shallow arch with a gently walkable paved deck and low stone parapets. Longitudinal crossing follows local Z. Weathered limestone matching a mountain village. Open arch beneath deck. Y+ up, Z+ front, X+ right.'
  });
  api.requireAsset({
    key: 'well', name: '村井', role: 'environment',
    dimensions: [2.3, 3.5, 2.3],
    prompt: 'One standalone old village well, circular gray stone rim, two oak posts supporting a small slate canopy, wooden winding spindle and bucket. Y+ up, Z+ front, X+ right. No surrounding ground.'
  });
  api.requireAsset({
    key: 'pine', name: '山松', role: 'environment',
    dimensions: [4, 10, 4],
    prompt: 'One standalone mountain pine tree, weathered brown trunk, irregular layered dark green needle canopy, slightly wind bent, exposed root flare. Y+ up, Z+ front, X+ right. No ground plane.'
  });
  api.requireAsset({
    key: 'boulder', name: '山岩', role: 'environment',
    dimensions: [3.8, 2.4, 3],
    prompt: 'One standalone angular weathered gray limestone boulder with natural cracks and small moss patches, suitable for a mountain valley. Y+ up, Z+ front, X+ right. No ground plane.'
  });

  const roadLines = [];
  const occupied = [];
  const bankRoads = [];
  function sample(p) {
    return api.environmentSample(p, { waterId: river });
  }
  function road(id, points, width) {
    for (let i = 1; i < points.length; i++) {
      const a = sample(points[i - 1]);
      const b = sample(points[i]);
      api.rampTerrain({
        start: points[i - 1], end: points[i], width: width + 0.8,
        startHeight: a.height, endHeight: b.height,
        softness: 0.65, strength: 0.85
      });
    }
    const result = api.route({
      id: id, points: points, width: width,
      curve: 'polyline', surface: 'paving', material: 'weathered gray cobblestone'
    });
    roadLines.push(points);
    return result;
  }

  for (let side = -1; side <= 1; side += 2) {
    const options = [11.5, 13, 14.5].map(function(x) {
      const points = [-39, -22, -5, 12, 29, 40].map(function(z) { return [side * x, z]; });
      const observations = points.map(sample);
      return {
        x: side * x,
        slope: observations.reduce(function(sum, s) { return sum + s.slope; }, 0),
        range: Math.max.apply(null, observations.map(function(s) { return s.height; })) -
          Math.min.apply(null, observations.map(function(s) { return s.height; }))
      };
    });
    options.sort(function(a, b) { return (a.slope + a.range * 0.2) - (b.slope + b.range * 0.2); });
    const inner = options[0].x;
    const outer = side * 29;
    bankRoads.push({ side: side, inner: inner, outer: outer });
    road('bank-lane-' + side, [[inner, -42], [inner, -28], [inner, -10], [inner, 8], [inner, 26], [inner, 40]], 3.2);
    road('upper-lane-' + side, [[outer, -40], [outer, -28], [outer, -10], [outer, 8], [outer, 26], [outer, 40]], 2.8);
    road('south-link-' + side, [[outer, -40], [inner, -40]], 2.8);
    road('north-link-' + side, [[outer, 40], [inner, 40]], 2.8);
  }

  [-28, 26].forEach(function(z, index) {
    bankRoads.forEach(function(bank) {
      road('bridge-approach-' + index + '-' + bank.side,
        [[bank.outer, z], [bank.inner, z], [bank.side * 4.2, z]], 3.6);
    });
    api.bridge({
      waterId: river, assetId: api.asset('bridge'),
      crossingCenter: [0, z], direction: [1, 0],
      dimensions: [3.8, 2, 8.4]
    });
  });

  const rows = [-35, -22, -9, 4, 17, 34];
  let houseNumber = 0;
  bankRoads.forEach(function(bank) {
    const strips = [
      { x: bank.side * 6.2, roadX: bank.inner, small: true },
      { x: bank.side * 21, roadX: bank.outer, small: false },
      { x: bank.side * 36, roadX: bank.outer, small: false }
    ];
    strips.forEach(function(strip) {
      rows.forEach(function(z) {
        const candidates = [-0.7, 0, 0.7].map(function(dz) {
          const p = [strip.x, z + dz];
          return { p: p, info: sample(p) };
        });
        candidates.sort(function(a, b) { return a.info.slope - b.info.slope; });
        const selected = candidates[0];
        const p = selected.p;
        const width = strip.small ? 4.6 : 5.6;
        const depth = strip.small ? 5.2 : 6.3;
        api.sculptTerrain({
          mode: 'flatten', point: p, radius: strip.small ? 3.8 : 4.5,
          targetHeight: selected.info.height, strength: 0.9
        });
        const ground = sample(p);
        const direction = strip.roadX > p[0] ? 1 : -1;
        const yaw = direction * Math.PI / 2;
        const entrance = [p[0] + direction * (depth / 2 + 0.25), p[1]];
        const access = [strip.roadX, p[1]];
        const accessSample = sample(access);
        api.rampTerrain({
          start: entrance, end: access, width: 1.8,
          startHeight: ground.height, endHeight: accessSample.height,
          softness: 0.6, strength: 1
        });
        const home = api.place({
          assetId: strip.small ? api.asset('small-house') : api.asset('stone-house', houseNumber % 2),
          name: '石屋' + (houseNumber + 1),
          position: p, rotationY: yaw,
          dimensions: [width, strip.small ? 6.2 : 7.1 + (houseNumber % 3) * 0.35, depth],
          role: 'structure'
        });
        api.foundation({
          under: [home], shape: 'rounded-rectangle',
          width: width + 0.45, depth: depth + 0.5,
          top: 'level', maxThickness: 3, material: 'rough limestone masonry'
        });
        api.route({
          id: 'door-path-' + houseNumber,
          points: [entrance, access], width: 1.7,
          surface: 'paving', curve: 'polyline', material: 'worn limestone paving'
        });
        roadLines.push([entrance, access]);
        occupied.push({ p: p, radius: 4.6 });
        houseNumber++;
      });
    });
  });

  const court = [-21, 26];
  const courtGround = sample(court);
  api.sculptTerrain({
    mode: 'flatten', point: court, radius: 4,
    targetHeight: courtGround.height, strength: 0.85
  });
  sample(court);
  api.surface({
    id: 'well-court', surface: 'paving', material: 'old limestone flags',
    region: { kind: 'circle', center: court, radius: 4 }
  });
  const well = api.place({ assetId: api.asset('well'), position: [-21, 28.1], role: 'environment' });
  api.foundation({ under: [well], width: 2.7, depth: 2.7, top: 'level', maxThickness: 1, material: 'limestone' });
  occupied.push({ p: court, radius: 5 });
  api.spawn([bankRoads[0].inner, -41], 0);

  function segmentDistance(p, a, b) {
    const dx = b[0] - a[0], dz = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / (dx * dx + dz * dz || 1)));
    return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dz);
  }
  function clear(p) {
    for (let i = 0; i < occupied.length; i++) {
      if (Math.hypot(p[0] - occupied[i].p[0], p[1] - occupied[i].p[1]) < occupied[i].radius + 2) return false;
    }
    for (let i = 0; i < roadLines.length; i++) {
      for (let j = 1; j < roadLines[i].length; j++) {
        if (segmentDistance(p, roadLines[i][j - 1], roadLines[i][j]) < 3) return false;
      }
    }
    return Math.abs(p[0]) > 4;
  }
  api.grass('valley-meadow', {
    kind: 'polygon', points: [[-47, -47], [47, -47], [47, 47], [-47, 47]]
  }, { preset: 'alpine-moss', density: 0.3, height: 0.22 });

  const trees = api.sampleProbabilityField({
    bounds: { minX: -45, maxX: 45, minZ: -45, maxZ: 45 },
    candidates: 650, maxPoints: 65, minDistance: 4,
    seed: api.seed + 13, cluster: { strength: 0.65, scale: 12 }
  }, function(p) {
    if (!clear(p)) return 0;
    const s = sample(p);
    return Math.abs(p[0]) > 39 ? 0.9 : (s.slope < 0.7 ? 0.15 : 0.06);
  });
  trees.forEach(function(p, i) {
    const scale = 0.8 + (i % 5) * 0.09;
    api.place({
      assetId: api.asset('pine'), position: p,
      rotationY: Math.random() * Math.PI * 2,
      dimensions: [4 * scale, 10 * scale, 4 * scale], role: 'environment'
    });
  });
  const rocks = api.sampleProbabilityField({
    bounds: { minX: -45, maxX: 45, minZ: -45, maxZ: 45 },
    candidates: 240, maxPoints: 22, minDistance: 4.5, seed: api.seed + 31
  }, function(p) {
    return clear(p) && Math.abs(p[0]) > 40 ? 0.85 : 0;
  });
  rocks.forEach(function(p) {
    api.place({ assetId: api.asset('boulder'), position: p, rotationY: Math.random() * 6.283185307, role: 'environment' });
  });
  if (trees.length === 0) api.place({ assetId: api.asset('pine'), position: [43, 42], role: 'environment' });
  if (rocks.length === 0) api.place({ assetId: api.asset('boulder'), position: [-44, 43], role: 'environment' });
}

function plan(api) {
  api.terrain('plain', { amplitude: 0.65, roughness: 0.16, seed: 566976230 });
  api.modifyTerrain({
    modifier: 'terrace',
    region: { kind: 'polygon', points: [[-47, -47], [27, -47], [27, 47], [-47, 47]] },
    amplitude: 0.45,
    softness: 0.8
  });
  const sea = api.water('coastal-ocean', {
    type: 'ocean',
    points: [[33, -48], [48, -48], [48, 48], [35, 48], [32, 25], [34, 0], [32, -24]],
    level: -0.15,
    depth: 5
  });
  api.surface({
    id: 'coastal-sand',
    surface: 'sand',
    region: { kind: 'path', points: [[30, -47], [29, -25], [31, 0], [29, 25], [32, 47]], width: 6 }
  });
  api.grass('coastal-low-grass', {
    kind: 'polygon',
    points: [[-47, -47], [27, -47], [28, 47], [-47, 47]]
  }, { preset: 'meadow', density: 0.25, height: 0.16 });

  function observe(p) {
    return api.environmentSample(p, { waterId: sea });
  }
  const alternatives = [[10, 12], [10, 20], [7, 5]];
  const observations = alternatives.map(function(p) { return observe(p); });
  let selected = 0;
  for (let i = 1; i < alternatives.length; i++) {
    if (observations[i].slope < observations[selected].slope &&
        observations[i].waterDistance > 12) selected = i;
  }
  const pad = alternatives[selected];
  const assemblySites = [[-26, -8], [-26, -17]];
  const assemblySamples = assemblySites.map(function(p) { return observe(p); });
  const assembly = assemblySamples[0].slope <= assemblySamples[1].slope ? assemblySites[0] : assemblySites[1];
  const control = [-28, -34];
  const fuel = [-19, 28];
  const supportSites = [control, fuel, [-37, 10], [-37, 34]];
  supportSites.forEach(observe);

  function grade(p, radius) {
    const before = observe(p);
    api.sculptTerrain({
      mode: 'flatten', point: p, radius: radius,
      strength: 1, targetHeight: before.height
    });
    return observe(p).height;
  }
  const padHeight = grade(pad, 14);
  grade(assembly, 12);
  grade(control, 9);
  grade(fuel, 10);
  grade([-37, 10], 7);
  grade([-37, 34], 6);

  function surface(id, points, width, type) {
    api.surface({ id: id, surface: type, region: { kind: 'path', points: points, width: width } });
  }
  function road(id, points, width) {
    for (let i = 1; i < points.length; i++) {
      const a = observe(points[i - 1]);
      const b = observe(points[i]);
      api.rampTerrain({
        start: points[i - 1], end: points[i], width: width + 1,
        startHeight: a.height, endHeight: b.height, softness: 0.65, strength: 0.9
      });
    }
    return api.route({ id: id, points: points, width: width, surface: 'paving', curve: 'polyline' });
  }

  api.requireAsset({
    key: 'rocket', name: '重型运载火箭', role: 'structure', dimensions: [3.4, 15.8, 3.4],
    prompt: 'One upright heavy orbital launch rocket, white cylindrical core, two slim attached side boosters, black interstage bands, rounded pointed payload fairing, realistic engines and subtle red markings. Landing feet absent. Y+ up, Z+ front, X+ right. Standalone vehicle, no launch pad.'
  });
  api.requireAsset({
    key: 'tower', name: '发射勤务塔', role: 'structure', dimensions: [3.5, 15.5, 4],
    prompt: 'One steel rocket umbilical service tower, open gray lattice truss, yellow access platforms, stairs, pipes, three short umbilical arms projecting toward local Z+, small red warning beacons. Y+ up, Z+ front toward rocket, X+ right. No rocket or ground slab.'
  });
  api.requireAsset({
    key: 'launchbase', name: '发射台座', role: 'structure', dimensions: [8, 1.5, 8],
    prompt: 'One heavy concrete rocket launch mount, square low structural platform with central engine opening, dark heat scorched lining, steel upper deck, water deluge pipes and side access stairs. Y+ up, Z+ front, X+ right. No rocket.'
  });
  api.requireAsset({
    key: 'assembly', name: '火箭总装厂房', role: 'structure', dimensions: [17, 11, 16],
    prompt: 'One large aerospace vehicle assembly building, tall rectangular white and pale gray metal clad industrial volume, blue vertical trim, huge closed segmented rocket transport door on Z+ facade, roof ventilation and small personnel door. Y+ up, Z+ entrance, X+ right. No surrounding scenery.'
  });
  api.requireAsset({
    key: 'control', name: '发射控制楼', role: 'structure', dimensions: [13, 5, 9],
    prompt: 'One modern two story launch control building, reinforced pale concrete, blue gray horizontal windows, flat roof with small antenna equipment, recessed central entrance and modest entrance canopy. Y+ up, Z+ entrance, X+ right.'
