  const gateHeight = api.environmentSample(gatePoint, { waterId: pool }).height;
  api.sculptTerrain({ mode: 'flatten', point: gatePoint, radius: 7, targetHeight: gateHeight, strength: 1 });
  api.environmentSample(gatePoint, { waterId: pool });
  const gate = api.place({ assetId: api.asset('gate'), position: gatePoint, rotationY: 0, role: 'structure' });
  api.foundation({ under: [gate], width: 12.5, depth: 4.5, top: 'level', maxThickness: 2, material: 'mossy sandstone' });

  const paths = [];
  function path(id, points, width, surface) {
    paths.push({ points: points, width: width });
    for (let i = 0; i < points.length - 1; i++) {
      const a = api.environmentSample(points[i], { waterId: pool });
      const b = api.environmentSample(points[i + 1], { waterId: pool });
      api.rampTerrain({ start: points[i], end: points[i + 1], width: width + 1, startHeight: a.height, endHeight: b.height, softness: 0.8, strength: 0.85 });
    }
    return api.route({ id: id, points: points, width: width, curve: 'polyline', surface: surface });
  }
  path('processional-axis', [[x, z + 12.8], [x, z + 20], [x, z + 29], gatePoint], 5, 'paving');
  path('jungle-approach', [gatePoint, [x + 1, 27], [x - 6, 34], [x - 13, 40], [x - 14, 45]], 3, 'soil');

  const occupied = [
    { x: x, z: z, w: 18, d: 16 },
    { x: court[0], z: court[1], w: 14, d: 13 },
    { x: gatePoint[0], z: gatePoint[1], w: 8, d: 4 }
  ];
  for (let side = -1; side <= 1; side += 2) {
    const sp = [x + side * 21, z + 7];
    const ss = api.environmentSample(sp, { waterId: pool });
    api.sculptTerrain({ mode: 'flatten', point: sp, radius: 6, targetHeight: ss.height, strength: 1 });
    api.environmentSample(sp, { waterId: pool });
    const yaw = -side * Math.PI / 2;
    const shrine = api.place({ assetId: api.asset('shrine'), position: sp, rotationY: yaw, role: 'structure' });
    api.foundation({ under: [shrine], width: 8.8, depth: 8.8, top: 'level', maxThickness: 3, material: 'aged sandstone' });
    path('side-access-' + side, [[x, z + 19], [x + side * 12, z + 19], [x + side * 16, z + 12], [x + side * 16.8, z + 7]], 2.5, 'paving');
    occupied.push({ x: sp[0], z: sp[1], w: 6, d: 6 });
    for (let j = 0; j < 4; j++) {
      const p = [x + side * 9.5, z + 17 + j * 4.1];
      const pillar = api.place({ assetId: api.asset('pillar'), position: p, rotationY: side * 0.12 });
      api.foundation({ under: [pillar], width: 2.4, depth: 2.4, top: 'level', maxThickness: 1.5, material: 'sandstone' });
    }
    for (let j = 0; j < 5; j++) {
      api.place({
        assetId: api.asset('rubble'), position: [x + side * (14 + Math.random() * 3), z - 9 + j * 6],
        rotationY: Math.random() * Math.PI * 2
      });
    }
  }
  const altar = api.place({ assetId: api.asset('altar'), position: [x - 5, courtGround, z + 24], rotationY: 0 });
  api.foundation({ under: [altar], width: 5.5, depth: 4.5, top: 'level', maxThickness: 1.5, material: 'sandstone' });

  function segmentDistance(p, a, b) {
    const dx = b[0] - a[0], dz = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / Math.max(0.0001, dx * dx + dz * dz)));
    return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dz);
  }
  function clear(p, margin) {
    for (let i = 0; i < occupied.length; i++) {
      const o = occupied[i];
      if (Math.abs(p[0] - o.x) < o.w + margin && Math.abs(p[1] - o.z) < o.d + margin) return false;
    }
    for (let i = 0; i < paths.length; i++) {
      for (let j = 0; j < paths[i].points.length - 1; j++) {
        if (segmentDistance(p, paths[i].points[j], paths[i].points[j + 1]) < paths[i].width / 2 + margin) return false;
      }
    }
    return true;
  }
  function vegetation(key, maxPoints, minDistance, margin, seed) {
    const points = api.sampleProbabilityField({
      bounds: { minX: -41, maxX: 41, minZ: -41, maxZ: 41 },
      maxPoints: maxPoints, candidates: 1500, minDistance: minDistance, seed: seed,
      cluster: { strength: 0.48, scale: 12, seed: seed + 1 }
    }, function (p) {
      if (!clear(p, margin)) return 0;
      const s = api.environmentSample(p, { waterId: pool });
      if (s.waterDistance < margin + 1 || s.height < -0.1) return 0;
      const edge = Math.max(Math.abs(p[0]), Math.abs(p[1])) / 41;
      return 0.35 + edge * 0.65;
    });
    points.forEach(function (p) {
      api.place({ assetId: api.asset(key), position: p, rotationY: Math.random() * Math.PI * 2 });
    });
  }
  vegetation('tree', 66, 7, 4, 354910827);
  vegetation('palm', 48, 4.5, 2, 354910828);
  vegetation('fern', 160, 2.1, 0.7, 354910829);
  api.grass('rainforest-floor', {
    kind: 'polygon', points: [[-46, -46], [46, -46], [46, 46], [-46, 46]]
  }, { preset: 'wetland', density: 0.38, height: 0.35, mix: 0.7 });
  api.spawn([x - 14, 44], 155);
}
